const { createClient } = require('@supabase/supabase-js');

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

// Paste the mapping generated by upload-to-supabase-storage.js here:
const mapping = {
  // '/uploads/filename.jpg': 'https://...supabase.../uploads/filename.jpg',
  // ...
};

function replaceUrl(url) {
  if (!url) return url;
  if (mapping[url]) return mapping[url];
  // If url is an array, map recursively
  if (Array.isArray(url)) return url.map(replaceUrl);
  return url;
}

async function updateTable(table, idField, fields) {
  const { data: rows, error } = await supabase.from(table).select('*');
  if (error) throw error;
  let updated = 0;
  for (const row of rows) {
    let changed = false;
    const updateObj = {};
    for (const field of fields) {
      let value = row[field];
      if (!value) continue;
      // Try to parse JSON fields
      let parsed = value;
      if (typeof value === 'string' && (value.startsWith('[') || value.startsWith('{'))) {
        try { parsed = JSON.parse(value); } catch {}
      }
      const replaced = replaceUrl(parsed);
      if (JSON.stringify(replaced) !== JSON.stringify(parsed)) {
        updateObj[field] = Array.isArray(replaced) || typeof replaced === 'object' ? JSON.stringify(replaced) : replaced;
        changed = true;
      }
    }
    if (changed) {
      const { error: updateError } = await supabase.from(table).update(updateObj).eq(idField, row[idField]);
      if (updateError) {
        console.error(`Error updating ${table} ${row[idField]}:`, updateError.message);
      } else {
        updated++;
        console.log(`Updated ${table} ${row[idField]}`);
      }
    }
  }
  console.log(`Table ${table}: Updated ${updated} records.`);
}

async function main() {
  await updateTable('properties', 'id', ['images', 'brochure', 'floorPlan', 'agent']);
  await updateTable('projects', 'id', ['images', 'brochure', 'floorPlans', 'masterPlan']);
  // Add more tables/fields if needed
  console.log('Done updating database URLs.');
}

main(); 